-- =======================================
-- 一个通用的 静态样条曲线工具, 用户传入一组节点数据, 构成单条曲线, 然后通过一个 t:[0,1] 可以采样到这条曲线上任何一个点的 平滑值;
--  目前支持的曲线类型:
--      CatmullRom:   能保证曲线一定经过每一个节点;
--      BSpline:      无比平滑, 连速度都是平滑的; 但不能保证一定经过每一个节点; 适合相机运动

-- 本工具专门针对 静态曲线做了优化(预计算), 不适合 runtime 会发生变化的曲线;

-- 计算公式参考:
-- https://www.youtube.com/watch?v=jvPPXbo87ds&list=PLeUKbKrkDo84cfuiE1UG_3K-ALVOA6b4L


---@class SplinesGeneric                 
local SplinesGeneric = Class('SplinesGeneric')
-- 外部访问时使用:
-- local SplinesGeneric = import('Game.IdolLive3D.Tools.SplinesGeneric')


-- ========================================================

---:
local Object = CS.UnityEngine.Object
local GameObject = CS.UnityEngine.GameObject
local Canvas = CS.UnityEngine.Canvas
local Physics = CS.UnityEngine.Physics
local LayerMask = CS.UnityEngine.LayerMask
local Mathf = CS.UnityEngine.Mathf
local Time = CS.UnityEngine.Time
local Matrix4x4 = CS.UnityEngine.Matrix4x4
local Vector3 = CS.UnityEngine.Vector3
local Vector4 = CS.UnityEngine.Vector4

--- funtoy:
local KTool = CS.Engine.Lib.KTool

-- ========================================================


-- 暂时仅支持这两种曲线:
SplinesGeneric.SplinesType = 
{ 
    CatmullRom  = 11,   -- 能保证曲线一定经过每一个节点; 但是当节点分布不合理时, 构成的曲线会变得奇怪;
    BSpline     = 12,   -- 无比平滑, 连速度都是平滑的; 但不能保证一定经过每一个节点; 适合相机运动
}


local CatmullRomMatrix = Matrix4x4(
    Vector4(  0,  2,  0,  0  ) * 0.5,
    Vector4( -1,  0,  1,  0  ) * 0.5,
    Vector4(  2, -5,  4, -1 )  * 0.5,
    Vector4( -1,  3, -3,  1 )  * 0.5
).transpose



local BSplineMatrix = Matrix4x4(
    Vector4(  1,  4,  1,  0  ) / 6.0,
    Vector4( -3,  0,  3,  0  ) / 6.0,
    Vector4(  3, -6,  3,  0 )  / 6.0,
    Vector4( -1,  3, -3,  1 )  / 6.0
).transpose


function SplinesGeneric._ChooseMatrix(splinesType_) 
    if splinesType_ == SplinesGeneric.SplinesType.CatmullRom then 
        return CatmullRomMatrix
    elseif splinesType_ == SplinesGeneric.SplinesType.BSpline  then
        return BSplineMatrix
    else 
        printError("参数类型异常: " .. tostring(splinesType_))
        return CatmullRomMatrix
    end
end


-- ========================================================

-- 通过传递大量函数指针, 来模拟 c# 中的泛型class SplinesGeneric<T>

---@param nodes_            table T[], T 为用户自定义类型
---@param splinesType_      table SplinesGeneric.SplinesType 两种曲线二选一
---@param nodeDefaultFunc_  function    T 类型的 无参构造函数       T Default()
---@param nodeAddFunc_      function    T 类型的 加法               T Add( T a, T b)
---@param nodeMinusFunc_    function    T 类型的 减法               T Minus( T a, T b)
---@param nodeScaleFunc_    function    T 类型的 标量乘法           T Scale( T a, float s)
---@param nodeSetTFunc_     function    改写 T 类型的元素 float t;  float SetT( T a, float t_)
---@param nodeGetTFunc_     function    读取 T 类型的元素 float t;  float GetT( T a )
function SplinesGeneric:__init( nodes_, splinesType_, nodeDefaultFunc_, nodeAddFunc_, nodeMinusFunc_, nodeScaleFunc_, nodeSetTFunc_, nodeGetTFunc_ )
    
    assert( type(nodes_) == "table" )
    assert( table.count(nodes_) >= 2 )
    assert( type(nodeDefaultFunc_) == "function" )
    assert( type(nodeAddFunc_) == "function" )
    assert( type(nodeMinusFunc_) == "function" )
    assert( type(nodeScaleFunc_) == "function" )
    assert( type(nodeSetTFunc_) == "function" )
    assert( type(nodeGetTFunc_) == "function" )

    local totalNum = table.count(nodes_)
    self.splinesType = splinesType_
    
    -- funcs:
    self.nodeDefaultFunc = nodeDefaultFunc_
    self.Add = nodeAddFunc_
    self.Minus = nodeMinusFunc_
    self.Scale = nodeScaleFunc_
    self.SetT = nodeSetTFunc_
    self.GetT = nodeGetTFunc_

    local prefixData = self.Add( nodes_[1],         self.Minus( nodes_[1],          nodes_[2] ) )           -- 额外的 前面一个节点
    local suffixData = self.Add( nodes_[totalNum],  self.Minus( nodes_[totalNum],   nodes_[totalNum-1] ) )  -- 额外的 后面一个节点
    self.SetT( prefixData, -1.0 )-- 这个的 t 值只需比 0 小
    self.SetT( suffixData,  2.0 )-- 这个的 t 值只需比 1 大
    

    self.curveNodes = {}        -- T[],                         totalNum+2 个元素
    self.preCalcNodeParams = {} -- {a0, a1, a2, a3}[], 每个元素类型为 T; totalNum 个元素

    table.insert( self.curveNodes, prefixData )
    for i=1, totalNum do 
        local t = (i-1.0) / (totalNum-1.0)
        self.SetT( nodes_[i], t )
        table.insert( self.curveNodes, nodes_[i] )
    end 
    table.insert( self.curveNodes, suffixData )

        -------- debug:
        -- print( "----- curveNodes: ------ " )
        -- for _,cn in pairs(self.curveNodes) do 
        --     print( cn:ToString() )
        -- end 

    -- 预计算, 提升 Calculate() 运算性能:
    for i=2, table.count(self.curveNodes)-2 do -- l,r
        table.insert( self.preCalcNodeParams, self:_PreCalc(i) )
    end 
end




function SplinesGeneric:__delete()
    self.curveNodes = nil 
    self.preCalcNodeParams = nil
    self.nodeDefaultFunc = nil
    self.Add = nil
    self.Minus = nil
    self.Scale = nil
    self.SetT = nil 
    self.GetT = nil
end



-- ===============================================================


---@param  t_  number, [0.0,1.0] 区间
---@return table 用户自定义 T 类型
function SplinesGeneric:Calculate( t_ ) 
    if t_ < 0.0 or t_ > 1.0  then 
        printError("参数异常, t_:" .. tostring(t_) )
        t_ = Mathf.Clamp01(t_)
    end

    for i=2, table.count(self.curveNodes)-2 do -- l,r
        local l_t = self.GetT( self.curveNodes[i] ) 
        local r_t = self.GetT( self.curveNodes[i+1] ) 
        if t_ >= l_t and t_ <= r_t  then
            return self:_DoCalc(i, t_)
        end
    end
    printError( "一个也没找到, 有异常, t_= " .. tostring(t_) )
    return self.nodeDefaultFunc()
end
 



function SplinesGeneric:_DoCalc( i_, t_ ) 
    local l_t = self.GetT( self.curveNodes[i_] ) 
    local r_t = self.GetT( self.curveNodes[i_+1] ) 
    t_ = KTool.Remap( l_t, r_t, 0.0, 1.0, t_ )
    ---
    local t1 = t_
    local t2 = t_*t_
    local t3 = t_*t_*t_
    local p = self.preCalcNodeParams[i_-1]
    return self.Add( p.a0, self.Add( self.Scale(p.a1,t1), self.Add( self.Scale(p.a2,t2),  self.Scale(p.a3,t3) )))
end



function SplinesGeneric:_PreCalc( i_ ) 

    local p0 = self.curveNodes[i_-1]
    local p1 = self.curveNodes[i_  ]
    local p2 = self.curveNodes[i_+1]
    local p3 = self.curveNodes[i_+2]

    local mtx = SplinesGeneric._ChooseMatrix(self.splinesType)    
    local a0 = self.Add( self.Scale(p0,mtx.m00), self.Add( self.Scale(p1,mtx.m01), self.Add( self.Scale(p2,mtx.m02),  self.Scale(p3,mtx.m03) )))
    local a1 = self.Add( self.Scale(p0,mtx.m10), self.Add( self.Scale(p1,mtx.m11), self.Add( self.Scale(p2,mtx.m12),  self.Scale(p3,mtx.m13) )))
    local a2 = self.Add( self.Scale(p0,mtx.m20), self.Add( self.Scale(p1,mtx.m21), self.Add( self.Scale(p2,mtx.m22),  self.Scale(p3,mtx.m23) )))
    local a3 = self.Add( self.Scale(p0,mtx.m30), self.Add( self.Scale(p1,mtx.m31), self.Add( self.Scale(p2,mtx.m32),  self.Scale(p3,mtx.m33) )))

    return { a0=a0, a1=a1, a2=a2, a3=a3 }
end





return SplinesGeneric
